  it("creates a new generated-cards deck with scheduler settings from the selector flow", async () => {
    createDeckMutateAsync.mockResolvedValue({
      id: 12,
      name: "Generated deck",
      description: null,
      deleted: false,
      client_id: "test",
      version: 1,
